/**
 * Text transforms that wire Texuli into a project's files. Each is
 * idempotent: applying it to its own output changes nothing. Nothing here
 * touches the file system.
 */
import { posix } from 'node:path';

/** First line of every stylesheet `texuli init` generates. */
export const CSS_HEADER =
  '/* @texuli/init: generated by `texuli init` and `texuli theme apply`. Keep the markers. */';
const THEME_START = /\/\* texuli:theme [a-z0-9-]+ \*\//;
const THEME_BLOCK = /\/\* texuli:theme [a-z0-9-]+ \*\/[\s\S]*?\/\* \/texuli:theme \*\//;
const BOOT_BLOCK = /<!-- texuli:no-flash -->[\s\S]*?<!-- \/texuli:no-flash -->/;

/** The generated stylesheet: base styles, then the theme between markers. */
export function stylesheet(themeId: string, themeCss: string): string {
  return `${CSS_HEADER}\n@import '@texuli/tokens/base.css';\n\n${themeBlock(themeId, themeCss)}\n`;
}

function themeBlock(themeId: string, themeCss: string): string {
  return `/* texuli:theme ${themeId} */\n${themeCss.trim()}\n/* /texuli:theme */`;
}

/** Whether `source` is a stylesheet `texuli init` generated (and kept its markers). */
export function isGeneratedStylesheet(source: string): boolean {
  return source.startsWith(CSS_HEADER) && THEME_START.test(source) && THEME_BLOCK.test(source);
}

/** Replaces the theme block of a generated stylesheet. */
export function withTheme(source: string, themeId: string, themeCss: string): string {
  return source.replace(THEME_BLOCK, () => themeBlock(themeId, themeCss));
}

/** The import specifier from `entry` to `css` (both project-relative). */
export function importSpecifier(entry: string, css: string): string {
  const relative = posix.relative(posix.dirname(entry), css);
  return relative.startsWith('.') ? relative : `./${relative}`;
}

function hasImport(source: string, specifier: string): boolean {
  return source.includes(`import '${specifier}'`) || source.includes(`import "${specifier}"`);
}

/** Adds `import '<specifier>';` to a JS, TS, Svelte or Astro entry (or creates one). */
export function withCssImport(source: string | null, file: string, specifier: string): string {
  const line = `import '${specifier}';`;
  if (file.endsWith('.svelte')) {
    if (source === null) {
      return `<script lang="ts">\n  ${line}\n  let { children } = $props();\n</script>\n\n{@render children()}\n`;
    }
    if (hasImport(source, specifier)) return source;
    const script = /<script\b[^>]*>/.exec(source);
    if (!script) return `<script lang="ts">\n  ${line}\n</script>\n\n${source}`;
    const at = script.index + script[0].length;
    return `${source.slice(0, at)}\n  ${line}${source.slice(at)}`;
  }
  if (file.endsWith('.astro')) {
    if (source === null) return astroLayout(line);
    if (hasImport(source, specifier)) return source;
    if (source.startsWith('---'))
      return source.replace(/^---[^\n]*\n/, (open) => `${open}${line}\n`);
    return `---\n${line}\n---\n\n${source}`;
  }
  if (source === null) return `${line}\n`;
  return hasImport(source, specifier) ? source : `${line}\n${source}`;
}

/** A minimal Astro layout for projects that have none. */
function astroLayout(importLine: string): string {
  return `---\n${importLine}\n---\n\n<!doctype html>\n<html lang="en">\n  <head>\n    <meta charset="utf-8" />\n    <meta name="viewport" content="width=device-width, initial-scale=1" />\n  </head>\n  <body>\n    <slot />\n  </body>\n</html>\n`;
}

/**
 * Puts the no-flash bootstrap first in `<head>` (between markers, replaced
 * on re-run) and sets `data-tx-theme` on `<html>`. Returns `null` when the
 * document has no `<html>` or `<head>` tag.
 */
export function withDocumentWiring(
  source: string,
  themeId: string,
  bootstrap: string,
  astro: boolean
): string | null {
  const html = /<html\b[^>]*>/i.exec(source);
  const head = /<head\b[^>]*>/i.exec(source);
  if (!html || !head) return null;
  const script = `<script${astro ? ' is:inline' : ''}>${bootstrap}</script>`;
  const block = `<!-- texuli:no-flash -->\n    ${script}\n    <!-- /texuli:no-flash -->`;
  let out = BOOT_BLOCK.test(source)
    ? source.replace(BOOT_BLOCK, () => block)
    : `${source.slice(0, head.index + head[0].length)}\n    ${block}${source.slice(head.index + head[0].length)}`;
  out = out.replace(/<html\b[^>]*>/i, (tag) =>
    /\sdata-tx-theme=/.test(tag)
      ? tag.replace(/\sdata-tx-theme=(?:"[^"]*"|'[^']*'|[^\s>]+)/, ` data-tx-theme="${themeId}"`)
      : tag.replace(/^<html/i, `<html data-tx-theme="${themeId}"`)
  );
  return out;
}

/** The `data-tx-theme` a document declares, if any. */
export function documentTheme(source: string): string | null {
  return /<html\b[^>]*\sdata-tx-theme="([^"]*)"/i.exec(source)?.[1] ?? null;
}
